package com.smarttask.notification.service;
import com.smarttask.notification.domain.*;import com.smarttask.notification.dto.NotificationDtos.*;import com.smarttask.notification.repository.*;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.*;
@Service
public class NotificationService{
 private final ReminderRepository reminders;private final NotificationRepository notifications;public NotificationService(ReminderRepository r,NotificationRepository n){reminders=r;notifications=n;}
 @Transactional public ReminderResponse createReminder(UUID u,ReminderRequest r){Reminder x=new Reminder();x.setUserId(u);x.setTaskId(r.taskId());x.setScheduledAt(r.scheduledAt());x.setType(r.type());return reminder(reminders.save(x));}
 @Transactional public ReminderResponse syncReminder(UUID u,UUID taskId,ReminderSyncRequest r){List<Reminder>existing=reminders.findAllByTaskIdAndUserId(taskId,u);Reminder x=existing.isEmpty()?new Reminder():existing.getFirst();x.setUserId(u);x.setTaskId(taskId);x.setScheduledAt(r.scheduledAt());x.setType(r.type());x.setStatus("PENDING");x.setProcessedAt(null);if(existing.size()>1)reminders.deleteAll(existing.subList(1,existing.size()));return reminder(reminders.save(x));}
 @Transactional public ReminderResponse updateReminder(UUID u,UUID id,ReminderRequest r){Reminder x=reminders.findById(id).filter(v->v.getUserId().equals(u)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy lời nhắc"));x.setTaskId(r.taskId());x.setScheduledAt(r.scheduledAt());x.setType(r.type());x.setStatus("PENDING");x.setProcessedAt(null);return reminder(x);}
 @Transactional public void deleteReminder(UUID u,UUID id){Reminder x=reminders.findById(id).filter(v->v.getUserId().equals(u)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));reminders.delete(x);}
 @Transactional public void deleteTaskReminders(UUID u,UUID taskId){reminders.deleteAll(reminders.findAllByTaskIdAndUserId(taskId,u));}
 @Transactional(readOnly=true) public PageResponse<NotificationResponse> list(UUID u,int page,int size){if(page<0||size<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Trang và kích thước trang không hợp lệ");int safeSize=Math.min(size,100);Page<Notification>p=notifications.findAllByUserIdOrderByCreatedAtDesc(u,PageRequest.of(page,safeSize));return new PageResponse<>(p.stream().map(this::notification).toList(),page,safeSize,p.getTotalElements(),p.getTotalPages());}
 @Transactional(readOnly=true) public UnreadCountResponse unread(UUID u){return new UnreadCountResponse(notifications.countByUserIdAndReadFalse(u));}
 @Transactional public NotificationResponse read(UUID u,UUID id){Notification n=notifications.findByIdAndUserId(id,u).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy thông báo"));n.setRead(true);n.setReadAt(Instant.now());return notification(n);}
 @Transactional public int readAll(UUID u){return notifications.markAllRead(u,Instant.now());}
 @Transactional public void processDue(){for(Reminder r:reminders.findTop100ByStatusAndScheduledAtLessThanEqualOrderByScheduledAtAsc("PENDING",Instant.now())){r.setStatus("PROCESSING");Notification n=new Notification();n.setUserId(r.getUserId());n.setTaskId(r.getTaskId());n.setType(r.getType());n.setTitle("Đã đến giờ xử lý công việc");n.setMessage("Một công việc của bạn đã đến thời gian được nhắc.");notifications.save(n);r.setStatus("PROCESSED");r.setProcessedAt(Instant.now());}}
 private ReminderResponse reminder(Reminder x){return new ReminderResponse(x.getId(),x.getTaskId(),x.getScheduledAt(),x.getType(),x.getStatus());}private NotificationResponse notification(Notification n){return new NotificationResponse(n.getId(),n.getTaskId(),n.getTitle(),n.getMessage(),n.getType(),n.isRead(),n.getCreatedAt(),n.getReadAt());}
}
